#!/usr/bin/env python3
# Curate Mahaperiyava / Deivathin Kural Volume 1 batch 046..065.
#
# Run from pramana repo root on branch:
#   mahaperiyava-dk-v1-corpus
#
# Recommended:
#   python ~/Downloads/curate_mahaperiyava_dk_v1_batch_046_065.py --commit --push
#
# This semantic curation pass creates 105 metadata-only teaching units across
# 20 chapters. All authority remains dk_attested.
#
# Evidence discipline:
# - exact DK source text remains private/gitignored;
# - every one of the 212 private source paragraphs is accounted for exactly once;
# - no historical-witness promotion is made in this pass;
# - no DK print check or primary-source verification is claimed;
# - all replacement-decoded source chapters are explicitly flagged;
# - context-sensitive social, political, caste/varna, historical, scientific,
#   health/effect, ritual, and comparative-religion claims remain attributed;
# - chapter 61's source title anomaly is preserved rather than silently corrected.

from __future__ import annotations

import argparse
