def die(message: str) -> None:
    raise SystemExit(f"ERROR: {message}")


def sh(cmd: list[str], *, capture: bool = False, check: bool = True):
    print("+", " ".join(cmd))
    return subprocess.run(
        cmd,
        cwd=ROOT,
        text=True,
        capture_output=capture,
        check=check,
    )


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def load_json(path: Path) -> Any:
    if not path.exists():
        die(f"Missing expected file: {path.relative_to(ROOT)}")
    return json.loads(path.read_text(encoding="utf-8"))


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        die(f"Missing expected file: {path.relative_to(ROOT)}")
    return [
        json.loads(line)
        for line in path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def write_jsonl(path: Path, rows: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")


def ensure_repo_state() -> None:
    if not (ROOT / ".git").exists():
        die("Run this script from the pramana repo root.")

    branch = sh(["git", "branch", "--show-current"], capture=True).stdout.strip()
    if branch != EXPECTED_BRANCH:
        die(f"Expected branch {EXPECTED_BRANCH!r}; found {branch!r}")

    dirty = sh(["git", "status", "--porcelain"], capture=True).stdout.strip()
    if dirty:
        die("Working tree must be clean before curation.\n" + dirty)

    for path in (PRIVATE_PACKET, SCHEMA, CATALOG, QUEUE):
        if not path.exists():
            die(f"Missing required input: {path.relative_to(ROOT)}")

    if TEACHING_RECORDS.exists() or CURATION_INDEX.exists():
        die("Batch 046..065 artifacts already exist; refusing a second application.")


def validate_private_packet(packet: dict[str, Any]) -> dict[str, Any]:
    actual_sha = hashlib.sha256(PRIVATE_PACKET.read_bytes()).hexdigest()
    if actual_sha != EXPECTED_PACKET_SHA256:
        die(
            "Private packet SHA drifted.\n"
            f"expected {EXPECTED_PACKET_SHA256}\n"
            f"actual   {actual_sha}"
        )

    if packet.get("packet_version") != "1.0":
        die(f"Expected packet version 1.0; found {packet.get('packet_version')!r}")

    selection = packet.get("selection", {})
    if (
        selection.get("selected_count") != 20
        or selection.get("start_ordinal") != 46
        or selection.get("end_ordinal") != 65
    ):
        die(f"Unexpected batch selection metadata: {selection}")

    if packet.get("rights", {}).get("public_export_allowed") is not False:
        die("Private packet rights gate is not fail-closed.")

    if packet.get("chapter_count") != 20:
        die("Expected chapter_count=20.")
    if packet.get("paragraph_count") != EXPECTED_PARAGRAPH_COUNT:
        die(
            f"Expected {EXPECTED_PARAGRAPH_COUNT} source paragraphs; "
            f"found {packet.get('paragraph_count')}"
        )

    by_ordinal = {c["ordinal"]: c for c in packet["chapters"]}
    if sorted(by_ordinal) != EXPECTED_ORDINALS:
        die(
            "Unexpected batch ordinals.\n"
            f"expected={EXPECTED_ORDINALS}\n"
            f"actual={sorted(by_ordinal)}"
        )

    actual_replacement = {
        ordinal
        for ordinal, chapter in by_ordinal.items()
        if chapter["decoded_as"] == "utf-8-replacement"
    }
    if actual_replacement != REPLACEMENT_DECODED_ORDINALS:
        die(
            "Replacement-decoded source set drifted.\n"
            f"expected={sorted(REPLACEMENT_DECODED_ORDINALS)}\n"
            f"actual={sorted(actual_replacement)}"
        )

    if len(CURATED_UNITS) != EXPECTED_UNIT_COUNT:
        die(f"Expected {EXPECTED_UNIT_COUNT} curated units; found {len(CURATED_UNITS)}")
    if len({u["id"] for u in CURATED_UNITS}) != EXPECTED_UNIT_COUNT:
        die("Curated teaching-unit IDs are not unique.")

    used: dict[int, list[str]] = defaultdict(list)

    for unit in CURATED_UNITS:
        if unit["proposed_authority"] != "dk_attested":
            die(f"Unexpected authority promotion: {unit['id']}")
        if unit.get("historical_witness") is not None:
            die(f"Unexpected historical witness: {unit['id']}")

        chapter = by_ordinal.get(unit["chapter_ordinal"])
        if not chapter:
            die(f"Missing source chapter for {unit['id']}")

        para_by_id = {p["id"]: p for p in chapter["paragraphs"]}
        if len(unit["source_paragraph_ids"]) != len(unit["source_paragraph_hashes"]):
            die(f"Paragraph id/hash count mismatch in {unit['id']}")

        for pid, expected_hash in zip(
            unit["source_paragraph_ids"],
            unit["source_paragraph_hashes"],
        ):
            para = para_by_id.get(pid)
            if not para:
                die(f"Missing paragraph {unit['chapter_ordinal']}:{pid}")
            if para["sha256"] != expected_hash:
                die(
                    f"Paragraph hash drift for {unit['id']} {pid}:\n"
                    f"expected {expected_hash}\n"
                    f"actual   {para['sha256']}"
                )
            used[unit["chapter_ordinal"]].append(pid)

        has_decode_flag = "source_decode_replacement" in unit.get("flags", [])
        if unit["chapter_ordinal"] in REPLACEMENT_DECODED_ORDINALS and not has_decode_flag:
            die(f"Replacement-decoded source unit lacks flag: {unit['id']}")
        if unit["chapter_ordinal"] not in REPLACEMENT_DECODED_ORDINALS and has_decode_flag:
            die(f"Clean UTF-8 source unit has replacement flag: {unit['id']}")

    total_used = 0
    for ordinal, chapter in by_ordinal.items():
        all_ids = [p["id"] for p in chapter["paragraphs"]]
        covered = used[ordinal]
        total_used += len(covered)
        if Counter(covered) != Counter(all_ids):
            missing = sorted(set(all_ids) - set(covered))
            duplicate = sorted(pid for pid, n in Counter(covered).items() if n > 1)
            extra = sorted(set(covered) - set(all_ids))
            die(
                f"Source coverage mismatch for ordinal {ordinal}: "
                f"missing={missing} duplicate={duplicate} extra={extra}"
            )

    if total_used != EXPECTED_PARAGRAPH_COUNT:
        die(
            f"Expected exactly {EXPECTED_PARAGRAPH_COUNT} covered source paragraphs; "
            f"found {total_used}"
        )

    return {
        "packet_sha256": actual_sha,
        "generated_at": packet.get("generated_at"),
        "chapter_count": packet["chapter_count"],
        "paragraph_count": packet["paragraph_count"],
        "by_ordinal": by_ordinal,
    }


