def schema_shape_validate(records: list[dict[str, Any]]) -> None:
    schema = load_json(SCHEMA)
    top_allowed = set(schema["properties"])
    top_required = set(schema["required"])
    id_re = re.compile(schema["properties"]["id"]["pattern"])

    for record in records:
        missing = top_required - set(record)
        extra = set(record) - top_allowed
        if missing:
            die(f"Schema required fields missing in {record['id']}: {sorted(missing)}")
        if extra:
            die(f"Schema extra fields in {record['id']}: {sorted(extra)}")
        if not id_re.match(record["id"]):
            die(f"Teaching-record ID fails schema pattern: {record['id']}")

        for field in ("source_locus", "attribution", "evidence_status", "rights"):
            spec = schema["properties"][field]
            obj = record[field]
            required = set(spec.get("required", []))
            allowed = set(spec.get("properties", {}))
            if required - set(obj):
                die(f"{record['id']}.{field} missing {sorted(required-set(obj))}")
            if spec.get("additionalProperties") is False and set(obj) - allowed:
                die(f"{record['id']}.{field} extra {sorted(set(obj)-allowed)}")

        if record["evidence_status"]["authority"] != "dk_attested":
            die(f"Unexpected authority promotion: {record['id']}")
        if record["evidence_status"]["print_check"] != "not_checked":
            die(f"Unexpected print-check promotion: {record['id']}")
        if record["evidence_status"]["primary_source_status"] != "unknown":
            die(f"Unexpected primary-source promotion: {record['id']}")
        if record["attribution"]["wording_status"] != "dk_wording_only":
            die(f"Unexpected wording status: {record['id']}")
        if (
            record["rights"]["source_text_tier"] == "restricted"
            and record["rights"]["public_export"] not in {"metadata_only", "none"}
        ):
            die(f"Restricted-rights gate violated: {record['id']}")


