def write_research_md(packet_meta: dict[str, Any]) -> None:
    counts = Counter(u["chapter_ordinal"] for u in CURATED_UNITS)
    flag_counts = Counter(
        flag for unit in CURATED_UNITS for flag in unit.get("flags", [])
    )

    lines = [
        "# Mahaperiyava — Deivathin Kural Volume 1 Batch 046–065",
        "",
        "## Result",
        "",
        "- New chapters curated: **20**",
        "- New teaching units: **105**",
        "- `dk_attested`: **105**",
        "- `earlier_witness_supported`: **0 new promotions**",
        "- `dk_print_checked`: **0**",
        "- `primary_source_verified`: **0**",
        "- Private review-packet paragraphs: **212**",
        "- Source paragraph coverage: **212/212 exactly once**",
        "- Explicitly excluded source blocks: **0**",
        "",
        "Exact Deivathin Kural wording remains private. Curator summaries are "
        "metadata, not quotations.",
        "",
        "## Evidence discipline",
        "",
        "- Official Kanchi DK establishes DK attestation only.",
        "- Historical-witness comparison is deferred.",
        "- No print check or primary-source verification is claimed.",
        "- Replacement-decoded chapters are explicitly flagged.",
        "- Chapter 61's mixed-script source title is preserved pending source QC.",
        "- Context-sensitive claims remain attributed rather than exported as "
        "neutral external fact.",
        "",
        "## High-context material",
        "",
        "- dharma-shastra authority versus individual conscience;",
        "- varna/caste and claims about earlier social organization;",
        "- contextual exceptions to ahimsa: war, punishment and sacrifice;",
        "- Hindu/Buddhist/Jain comparative claims;",
        "- ancestor rites and unseen ritual transmission;",
        "- hagiographic claims about perfected truthfulness;",
        "- dietary and plant-sentience claims using scientific language;",
        "- colonial-era cultural and political claims about swarajya;",
        "- claims that temples, moral exemplars, education, or service causally "
        "change society or spiritual states.",
        "",
        "## Units per chapter",
        "",
    ]

    for ordinal in sorted(counts):
        title = packet_meta["by_ordinal"][ordinal]["title_ta"]
        lines.append(f"- {ordinal:03d} `{title}`: **{counts[ordinal]}**")

    lines += ["", "## Flag highlights", ""]
    for flag, count in sorted(flag_counts.items(), key=lambda x: (-x[1], x[0])):
        lines.append(f"- `{flag}`: **{count}**")

    lines += [
        "",
        "## Next gate",
        "",
        "Run a targeted 1957–58 historical-witness pass only on high-yield "
        "claims with plausible earlier parallels: common dharma disciplines, "
        "ahimsa/satya, puja/bhakti, service, desire/anger, and selected "
        "dharma-shastra formulations. Do not promote caste/varna, political, "
        "historical, or comparative-religion claims merely because a related "
        "theme appears in an earlier collection.",
        "",
    ]

    RESEARCH_MD.parent.mkdir(parents=True, exist_ok=True)
    RESEARCH_MD.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def install_repo_script() -> None:
    REPO_SCRIPT.parent.mkdir(parents=True, exist_ok=True)
    src = Path(__file__).resolve()
    if src != REPO_SCRIPT.resolve():
        shutil.copyfile(src, REPO_SCRIPT)
        REPO_SCRIPT.chmod(0o755)


def snapshot_managed():
    return {p: (p.read_bytes() if p.exists() else None) for p in MANAGED}


def restore_managed(snapshot) -> None:
    print("\n=== Validation failed: restoring managed files ===")
    sh(["git", "reset"], check=False)
    for path, old in snapshot.items():
        if old is None:
            if path.exists():
                path.unlink()
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(old)
    sh(["git", "status", "--short"], check=False)


def validate_after(records, index) -> None:
    if len(records) != EXPECTED_UNIT_COUNT:
        die(f"Expected 105 records; found {len(records)}")

    if Counter(r["evidence_status"]["authority"] for r in records) != Counter({"dk_attested": 105}):
        die("Authority distribution drifted.")

    actual_counts = Counter(r["source_locus"]["chapter_ordinal"] for r in records)
    if actual_counts != Counter(EXPECTED_UNIT_COUNTS):
        die(
            "Chapter unit-count drift.\n"
            f"expected={EXPECTED_UNIT_COUNTS}\nactual={dict(actual_counts)}"
        )

    if index["source_coverage"]["covered_paragraph_count"] != EXPECTED_PARAGRAPH_COUNT:
        die("Source paragraph coverage drifted.")


def run_checks() -> None:
    print("\n=== Repo checks ===")
    sh(["git", "diff", "--check"])
    sh([sys.executable, "-m", "pytest", "-q"])
    sh([sys.executable, "scripts/audit_snapshots.py"])
    sh(["git", "diff", "--stat"])
    sh(["git", "status", "--short"])


def commit_changes() -> None:
    paths = [str(p.relative_to(ROOT)) for p in MANAGED if p.exists()]
    sh(["git", "add", "--", *paths])

    unstaged = sh(["git", "diff", "--name-only"], capture=True).stdout.strip()
    if unstaged:
        die("Unexpected unstaged changes remain; refusing to commit.\n" + unstaged)

    staged = sh(["git", "diff", "--cached", "--name-only"], capture=True).stdout.strip()
    if not staged:
        die("Nothing staged to commit.")

    print("\nStaged files:")
    print(staged)
    sh(["git", "commit", "-m", "Curate Mahaperiyava DK V1 batch 046-065"])


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--commit", action="store_true")
    parser.add_argument("--push", action="store_true")
    args = parser.parse_args()

    if args.push and not args.commit:
        die("--push requires --commit")

    ensure_repo_state()
    before = snapshot_managed()

    try:
        packet = load_json(PRIVATE_PACKET)
        packet_meta = validate_private_packet(packet)
        catalog = load_json(CATALOG)

        records = make_teaching_records(packet_meta, catalog)
        schema_shape_validate(records)
        index = make_curation_index(packet_meta, records)

        write_jsonl(TEACHING_RECORDS, records)
        write_json(CURATION_INDEX, index)
        update_queue_and_catalog(catalog)
        write_tests()
        write_research_md(packet_meta)
        install_repo_script()
        validate_after(records, index)

        print("\n=== Batch 046..065 curation summary ===")
        print("Chapters curated:              20")
        print("Teaching units:               105")
        print("Source paragraphs:            212")
        print("Paragraph coverage:       212/212")
        print("dk_attested:                  105")
        print("earlier witness promotions:     0")
        print("print checked:                  0")
        print("primary verified:               0")
        print("source exclusions:              0")
        print("Tracked exact DK source text: NONE")

        run_checks()

    except Exception:
        restore_managed(before)
        raise

    if args.commit:
        commit_changes()
    else:
        print("\nChanges validated but not committed.")

    if args.push:
        sh(["git", "push", "origin", EXPECTED_BRANCH])

    print("\n=== Final ===")
    sh(["git", "status", "--short"])
    sh(["git", "log", "-5", "--oneline"])


if __name__ == "__main__":
    main()
